using System.Collections.Generic;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "ForgeDiceOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/ForgeDiceOmenData")]
public class ForgeDiceOmenData : OmenData
{
	[SerializeField]
	private DiceRewardForgeModifier diceRewardForgeModifier;

	public override void Initialize(OmenInstance omenInstance)
	{
		ReferenceSingleton<MiscOmensHandler>.Instance.ForgeSafeDiceRewardForgeModifier = diceRewardForgeModifier;
		if (!ReferenceSingleton<AssetsReference>.Instance.PlayerCurrentOmens.PlayerHasBlessing(this))
		{
			List<Dice> allDiceFromSpecificTier = ReferenceSingleton<AssetsReference>.Instance.DicePool.GetAllDiceFromSpecificTier(ReferenceSingleton<AssetsReference>.Instance.SafeDieTier);
			for (int i = 0; i < allDiceFromSpecificTier.Count; i++)
			{
				ReferenceSingleton<AssetsReference>.Instance.DicePool.DecreaseDiceAmount(allDiceFromSpecificTier[i], 1);
			}
			for (int j = 0; j < allDiceFromSpecificTier.Count; j++)
			{
				allDiceFromSpecificTier[j] = diceRewardForgeModifier.GetModifiedDice(allDiceFromSpecificTier[j]);
				ReferenceSingleton<AssetsReference>.Instance.DicePool.IncreaseDiceAmount(allDiceFromSpecificTier[j], 1);
			}
		}
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<MiscOmensHandler>.Instance.ForgeSafeDiceRewardForgeModifier = null;
	}
}
